import { useEffect, useMemo, useState } from 'react';
import styles from './Home.module.scss';
import { UnauthenticatedHeader, AuthenticatedHeader } from '../../components/Header/Header';
import { useAuth } from '../../contexts/AuthContext';
import Hero from '../../components/Hero/Hero';
import ImageCarousel from '../../components/ImageCarousel/ImageCarousel';
import PostGrid from '../../components/PostGrid/PostGrid';
import FAQ from '../../components/FAQ/FAQ';
import { api } from '../../utils/api';

const extractList = (payload) => {
  if (Array.isArray(payload?.data)) {
    return payload.data;
  }

  if (Array.isArray(payload)) {
    return payload;
  }

  return [];
};

const buildProfileStats = (posts) => {
  const statsByUserId = new Map();

  posts.forEach((post) => {
    const authorId = post.author_id || post.author?.id || post.author?.ID;

    if (!authorId) {
      return;
    }

    const currentStats = statsByUserId.get(authorId) || {
      posts: 0,
      likes: 0,
      comments: 0,
      popularityScore: 0,
    };

    const likesCount = Array.isArray(post.likes) ? post.likes.length : 0;
    const commentsCount = Array.isArray(post.comments) ? post.comments.length : 0;

    currentStats.posts += 1;
    currentStats.likes += likesCount;
    currentStats.comments += commentsCount;
    currentStats.popularityScore += (likesCount * 2) + commentsCount + 3;

    statsByUserId.set(authorId, currentStats);
  });

  return statsByUserId;
};

export default function Home() {
  const { isAuthenticated } = useAuth();
  const [users, setUsers] = useState([]);
  const [posts, setPosts] = useState([]);
  const [loadingProfiles, setLoadingProfiles] = useState(true);
  const [profilesError, setProfilesError] = useState('');

  useEffect(() => {
    let isCancelled = false;

    const loadHomeData = async () => {
      try {
        setLoadingProfiles(true);
        setProfilesError('');

        const [usersResponse, postsResponse] = await Promise.all([
          api.get('/users/'),
          api.get('/posts'),
        ]);

        if (isCancelled) {
          return;
        }

        setUsers(extractList(usersResponse));
        setPosts(extractList(postsResponse));
      } catch (error) {
        if (!isCancelled) {
          setProfilesError(error.message || 'Не успяхме да заредим профилите.');
        }
      } finally {
        if (!isCancelled) {
          setLoadingProfiles(false);
        }
      }
    };

    loadHomeData();

    return () => {
      isCancelled = true;
    };
  }, []);

  const enrichedProfiles = useMemo(() => {
    const profileStats = buildProfileStats(posts);

    return users.map((user) => {
      const userId = user.id || user.ID;

      return {
        ...user,
        stats: profileStats.get(userId) || {
          posts: 0,
          likes: 0,
          comments: 0,
          popularityScore: 0,
        },
      };
    });
  }, [posts, users]);

  const discoverProfiles = useMemo(
    () => [...enrichedProfiles].sort((leftProfile, rightProfile) => (
      new Date(rightProfile.created_at || 0).getTime() - new Date(leftProfile.created_at || 0).getTime()
    )),
    [enrichedProfiles],
  );

  const popularProfiles = useMemo(
    () => [...enrichedProfiles].sort((leftProfile, rightProfile) => {
      const scoreDifference = (rightProfile.stats?.popularityScore || 0) - (leftProfile.stats?.popularityScore || 0);

      if (scoreDifference !== 0) {
        return scoreDifference;
      }

      return (rightProfile.stats?.posts || 0) - (leftProfile.stats?.posts || 0);
    }),
    [enrichedProfiles],
  );

  return (
    <div className={styles.home}>
      {isAuthenticated ? <AuthenticatedHeader /> : <UnauthenticatedHeader />}
      <Hero />
      <ImageCarousel
        profiles={discoverProfiles}
        loading={loadingProfiles}
        error={profilesError}
      />
      <PostGrid
        profiles={popularProfiles}
        loading={loadingProfiles}
        error={profilesError}
      />
      <FAQ />
    </div>
  );
}
